import { useState, useCallback } from "react";
import type {
  GameState,
  LevelData,
  TileType,
  Rotation,
} from "~/engine/types";
import { posKey } from "~/engine/utils";
import { simulateTraversal } from "~/engine/traversal";

function createInitialState(level: LevelData): GameState {
  return {
    placedTiles: new Map(),
    selectedTileType: null,
    remainingInventory: { ...level.inventory },
    phase: "placing",
    luckyPosition: null,
    luckyDirection: null,
    traversalPath: [],
    removeMode: false,
  };
}

export function useGameState(level: LevelData) {
  const [state, setState] = useState<GameState>(() =>
    createInitialState(level)
  );

  const selectTile = useCallback((type: TileType | null) => {
    setState((s) => ({
      ...s,
      selectedTileType: type,
      removeMode: type ? false : s.removeMode,
    }));
  }, []);

  const toggleRemoveMode = useCallback(() => {
    setState((s) => ({
      ...s,
      removeMode: !s.removeMode,
      selectedTileType: null,
    }));
  }, []);

  const placeTile = useCallback(
    (row: number, col: number) => {
      setState((s) => {
        if (s.phase !== "placing") return s;
        if (!s.selectedTileType) return s;

        const key = posKey(row, col);
        const startKey = posKey(level.start.row, level.start.col);
        const goalKey = posKey(level.goal.row, level.goal.col);
        const obstacleKeys = new Set(
          level.obstacles.map((o) => posKey(o.row, o.col))
        );
        if (key === startKey || key === goalKey || obstacleKeys.has(key))
          return s;

        const existing = s.placedTiles.get(key);
        const newInventory = { ...s.remainingInventory };

        // Return old tile to inventory if replacing
        if (existing) {
          newInventory[existing.type]++;
        }

        // Consume from inventory
        if (newInventory[s.selectedTileType] <= 0) return s;
        newInventory[s.selectedTileType]--;

        const newTiles = new Map(s.placedTiles);
        newTiles.set(key, { type: s.selectedTileType, rotation: 0 as Rotation });

        return {
          ...s,
          placedTiles: newTiles,
          remainingInventory: newInventory,
        };
      });
    },
    [level]
  );

  const rotateTile = useCallback((row: number, col: number) => {
    setState((s) => {
      if (s.phase !== "placing") return s;
      const key = posKey(row, col);
      const tile = s.placedTiles.get(key);
      if (!tile) return s;

      const newTiles = new Map(s.placedTiles);
      newTiles.set(key, {
        ...tile,
        rotation: ((tile.rotation + 1) % 4) as Rotation,
      });
      return { ...s, placedTiles: newTiles };
    });
  }, []);

  const moveTile = useCallback(
    (fromRow: number, fromCol: number, toRow: number, toCol: number) => {
      setState((s) => {
        if (s.phase !== "placing") return s;
        const fromKey = posKey(fromRow, fromCol);
        const toKey = posKey(toRow, toCol);
        if (fromKey === toKey) return s;

        const tile = s.placedTiles.get(fromKey);
        if (!tile) return s;

        // Can't drop on start, goal, obstacle, or existing tile
        const startKey = posKey(level.start.row, level.start.col);
        const goalKey = posKey(level.goal.row, level.goal.col);
        const obstacleKeys = new Set(
          level.obstacles.map((o) => posKey(o.row, o.col))
        );
        if (toKey === startKey || toKey === goalKey || obstacleKeys.has(toKey)) return s;
        if (s.placedTiles.has(toKey)) return s;

        // Bounds check
        if (toRow < 0 || toRow >= level.height || toCol < 0 || toCol >= level.width) return s;

        const newTiles = new Map(s.placedTiles);
        newTiles.delete(fromKey);
        newTiles.set(toKey, tile);

        return { ...s, placedTiles: newTiles };
      });
    },
    [level]
  );

  const removeTile = useCallback((row: number, col: number) => {
    setState((s) => {
      if (s.phase !== "placing") return s;
      const key = posKey(row, col);
      const tile = s.placedTiles.get(key);
      if (!tile) return s;

      const newTiles = new Map(s.placedTiles);
      newTiles.delete(key);

      const newInventory = { ...s.remainingInventory };
      newInventory[tile.type]++;

      return {
        ...s,
        placedTiles: newTiles,
        remainingInventory: newInventory,
      };
    });
  }, []);

  const runSimulation = useCallback(() => {
    setState((s) => {
      if (s.phase !== "placing") return s;
      const result = simulateTraversal(level, s.placedTiles);
      return {
        ...s,
        phase: result.success ? "success" : "failure",
        traversalPath: result.path,
        failReason: result.failReason,
        removeMode: false,
      };
    });
  }, [level]);

  const resetBoard = useCallback(() => {
    setState(createInitialState(level));
  }, [level]);

  const resetForLevel = useCallback(
    (newLevel: LevelData) => {
      setState(createInitialState(newLevel));
    },
    []
  );

  return {
    state,
    selectTile,
    toggleRemoveMode,
    placeTile,
    rotateTile,
    moveTile,
    removeTile,
    runSimulation,
    resetBoard,
    resetForLevel,
  };
}

import { useCallback, useEffect, useMemo, useState } from "react";
import { getLevelById, levels, worlds } from "~/engine/levels";
import { useGameState } from "~/hooks/useGameState";
import { completeLevel, loadSave } from "~/lib/persistence";
import { posKey } from "~/engine/utils";
import type { LevelData } from "~/engine/types";

export function useGameSession(level: LevelData) {
  const [showComplete, setShowComplete] = useState(false);
  const [settings, setSettings] = useState({ highContrast: false });

  useEffect(() => {
    const save = loadSave();
    setSettings(save.settings);
  }, []);

  const gameState = useGameState(level);
  const { state, selectTile, toggleRemoveMode, placeTile, rotateTile, removeTile, runSimulation, resetBoard } = gameState;

  const world = worlds.find((w) => w.id === level.worldId);
  const tilesUsed = state.placedTiles.size;

  const clovers = useMemo(() => {
    if (state.phase !== "success") return 0;
    if (tilesUsed <= level.par) return 3;
    if (tilesUsed <= level.par + 1) return 2;
    return 1;
  }, [state.phase, tilesUsed, level.par]);

  useEffect(() => {
    if (state.phase === "success") {
      completeLevel(level.id, clovers);
      const timer = setTimeout(() => setShowComplete(true), 1500);
      return () => clearTimeout(timer);
    } else {
      setShowComplete(false);
    }
  }, [state.phase, level.id, clovers]);

  const handleCellClick = useCallback(
    (row: number, col: number) => {
      if (state.phase !== "placing") return;

      const key = posKey(row, col);
      const startKey = posKey(level.start.row, level.start.col);
      const goalKey = posKey(level.goal.row, level.goal.col);
      const obstacleKeys = new Set(
        level.obstacles.map((o) => posKey(o.row, o.col))
      );

      if (key === startKey || key === goalKey || obstacleKeys.has(key)) return;

      if (state.removeMode) {
        if (state.placedTiles.has(key)) removeTile(row, col);
        return;
      }

      if (state.placedTiles.has(key)) {
        rotateTile(row, col);
        return;
      }

      if (state.selectedTileType) {
        placeTile(row, col);
      }
    },
    [state.phase, state.selectedTileType, state.placedTiles, state.removeMode, level, placeTile, rotateTile, removeTile]
  );

  const handleCellRightClick = useCallback(
    (row: number, col: number) => {
      removeTile(row, col);
    },
    [removeTile]
  );

  const handleRun = useCallback(() => {
    runSimulation();
  }, [runSimulation]);

  const handleReset = useCallback(() => {
    resetBoard();
  }, [resetBoard]);

  const handleSelectTile = useCallback(
    (type: import("~/engine/types").TileType | null) => {
      selectTile(type);
    },
    [selectTile]
  );

  const currentIdx = levels.findIndex((l) => l.id === level.id);
  const nextLevel = currentIdx >= 0 && currentIdx < levels.length - 1
    ? levels[currentIdx + 1]
    : null;

  return {
    state,
    settings,
    world,
    tilesUsed,
    clovers,
    showComplete,
    nextLevel,
    handleCellClick,
    handleCellRightClick,
    handleRun,
    handleReset,
    handleSelectTile,
    toggleRemoveMode,
    moveTile: gameState.moveTile,
  };
}

import { useParams, useNavigate } from "react-router";
import { useMemo } from "react";
import { getLevelById, levels } from "~/engine/levels";
import { useGameSession } from "~/hooks/useGameSession";
import { GameBoard } from "~/components/GameBoard";
import { TileInventory, TilePreview } from "~/components/TileInventory";
import { GameHUD } from "~/components/GameHUD";
import { LevelComplete } from "~/components/LevelComplete";
import { useState } from "react";

export default function Play() {
  const { levelId } = useParams();
  const navigate = useNavigate();
  const [currentLevelId, setCurrentLevelId] = useState(levelId);

  const level = useMemo(
    () => getLevelById(currentLevelId || ""),
    [currentLevelId]
  );

  if (!level) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <p className="text-emerald-800 font-bold text-lg mb-3">Level not found</p>
          <button
            onClick={() => navigate("/worlds")}
            className="text-base text-emerald-600 hover:text-emerald-700 font-medium"
          >
            Back to levels
          </button>
        </div>
      </div>
    );
  }

  return <PlayLevel key={currentLevelId} level={level} onChangeLevel={setCurrentLevelId} />;
}

function PlayLevel({
  level,
  onChangeLevel,
}: {
  level: NonNullable<ReturnType<typeof getLevelById>>;
  onChangeLevel: (id: string) => void;
}) {
  const navigate = useNavigate();

  const {
    state,
    settings,
    world,
    tilesUsed,
    clovers,
    showComplete,
    nextLevel,
    handleCellClick,
    handleCellRightClick,
    handleRun,
    handleReset,
    handleSelectTile,
    toggleRemoveMode,
    moveTile,
  } = useGameSession(level);

  return (
    <div className="min-h-dvh bg-gradient-to-b from-green-100 via-emerald-50 to-amber-50/50 flex flex-col items-center px-2 sm:px-4 py-3 gap-2 select-none">
      <GameHUD
        levelName={level.name}
        worldName={world?.name || ""}
        phase={state.phase}
        failReason={state.failReason}
        tilesRemaining={state.remainingInventory.straight + state.remainingInventory.curve}
        onRun={handleRun}
        onReset={handleReset}
        onBack={() => navigate("/worlds")}
      />

      {/* Hint */}
      {level.hint && state.phase === "placing" && tilesUsed === 0 && (
        <div className="text-sm text-amber-800 bg-amber-100/60 px-4 py-2 rounded-xl animate-slideUp max-w-md text-center">
          {level.hint}
        </div>
      )}

      {/* Board + Inventory */}
      <div className="flex flex-col sm:flex-row items-center sm:items-start gap-0 w-full max-w-2xl">
        <div className="w-full sm:w-auto sm:flex-1 sm:min-w-0">
          <GameBoard
            level={level}
            state={state}
            onCellClick={handleCellClick}
            onCellRightClick={handleCellRightClick}
            onMoveTile={moveTile}
            highContrast={settings.highContrast}
          />
        </div>

        {/* Desktop: vertical sidebar */}
        <div className="hidden sm:block shrink-0">
          <TileInventory
            remaining={state.remainingInventory}
            selectedType={state.selectedTileType}
            onSelect={handleSelectTile}
            disabled={state.phase !== "placing"}
            removeMode={state.removeMode}
            onToggleRemoveMode={toggleRemoveMode}
          />
        </div>

        {/* Mobile: horizontal bar below board */}
        <div className="sm:hidden">
          <MobileInventory
            remaining={state.remainingInventory}
            selectedType={state.selectedTileType}
            onSelect={handleSelectTile}
            disabled={state.phase !== "placing"}
            removeMode={state.removeMode}
            onToggleRemoveMode={toggleRemoveMode}
          />
        </div>
      </div>

      {showComplete && state.phase === "success" && (
        <LevelComplete
          levelName={level.name}
          tilesUsed={tilesUsed}
          par={level.par}
          clovers={clovers}
          hasNextLevel={!!nextLevel}
          onNext={() => {
            if (nextLevel) {
              onChangeLevel(nextLevel.id);
              navigate(`/play/${nextLevel.id}`, { replace: true });
            }
          }}
          onReplay={handleReset}
          onBack={() => navigate("/worlds")}
        />
      )}
    </div>
  );
}

// Horizontal inventory for mobile
function MobileInventory({
  remaining,
  selectedType,
  onSelect,
  disabled,
  removeMode,
  onToggleRemoveMode,
}: {
  remaining: { straight: number; curve: number };
  selectedType: import("~/engine/types").TileType | null;
  onSelect: (type: import("~/engine/types").TileType | null) => void;
  disabled?: boolean;
  removeMode?: boolean;
  onToggleRemoveMode?: () => void;
}) {
  const tiles: { type: import("~/engine/types").TileType; key: "straight" | "curve" }[] = [
    { type: "straight", key: "straight" },
    { type: "curve", key: "curve" },
  ];

  return (
    <div className="bg-white/90 backdrop-blur-sm rounded-2xl shadow-lg border border-gray-200 py-2 px-3 flex items-center gap-3 mt-2">
      {tiles.map(({ type, key }) => {
        const count = remaining[key];
        const isSelected = selectedType === type && !removeMode;
        const isEmpty = count <= 0;
        const available = !disabled && !isEmpty;

        return (
          <button
            key={type}
            onClick={() => {
              if (!available) return;
              if (onToggleRemoveMode && removeMode) onToggleRemoveMode();
              onSelect(isSelected ? null : type);
            }}
            disabled={!available}
            className={`
              flex items-center gap-2 px-3 py-2 rounded-xl transition-all select-none
              ${isSelected
                ? "bg-teal-100 ring-2 ring-teal-500"
                : isEmpty
                  ? "opacity-30 cursor-not-allowed"
                  : "hover:bg-teal-50 cursor-pointer"
              }
            `}
          >
            <TilePreview type={type} size={40} selected={isSelected} />
            <span className={`text-base font-bold tabular-nums px-1.5 py-0.5 rounded-md ${
              isSelected ? "bg-teal-200 text-teal-800" : "bg-gray-100 text-gray-500"
            }`}>
              {count}
            </span>
          </button>
        );
      })}

      {/* Divider */}
      <div className="w-px h-8 bg-gray-200" />

      {/* Remove */}
      <button
        onClick={() => {
          if (disabled) return;
          onSelect(null);
          onToggleRemoveMode?.();
        }}
        disabled={disabled}
        className={`
          p-2 rounded-xl transition-all select-none
          ${removeMode
            ? "bg-red-100 ring-2 ring-red-400"
            : disabled
              ? "opacity-30 cursor-not-allowed"
              : "hover:bg-red-50 cursor-pointer"
          }
        `}
        title="Remove placed tiles"
      >
        <svg width="22" height="22" viewBox="0 0 22 22" fill="none">
          <path d="M6 6l10 10M16 6L6 16"
            stroke={removeMode ? "#ef4444" : "#9ca3af"}
            strokeWidth="2.5" strokeLinecap="round" />
        </svg>
      </button>
    </div>
  );
}
